insert into public.ucapan (created_at, nama_guru, pesan, pengirim, warna) values
  (now() - interval '7 hours', 'Pak Darto, guru Fisika SMA', 'Dulu saya paling takut sama Bapak. Sekarang saya kerja jadi teknisi dan tiap hari pakai rumus yang Bapak paksa kami hafalkan. Terima kasih, Pak.', 'Rudi, IPA 2 angkatan 2014', 'putih'),
  (now() - interval '6 hours', 'Bu Wati', 'Ibu yang ngajarin saya baca waktu kelas 1 SD. Sampai sekarang saya masih ingat suara Ibu waktu mengeja "i-bu bu-di".', null, 'kuning'),
  (now() - interval '5 hours', 'Bu Lestari, wali kelas 9C', 'Makasih udah nggak nyerah sama kelas kami yang paling ribut satu sekolah. Maaf ya Bu, papan tulisnya sering kami coret-coret.', 'Anak-anak 9C', 'merah_muda'),
  (now() - interval '4 hours', 'Pak Haris', 'Bapak yang bilang tulisan saya bagus waktu semua orang bilang jelek. Sekarang saya jadi penulis. Kalimat itu saya simpan terus.', 'Nadia', 'biru_muda'),
  (now() - interval '3 hours', 'Bu Retno, dosen Statistika', 'Skripsi saya selesai karena Ibu mau balas chat jam sepuluh malam. Semoga Ibu sehat terus.', 'Fajar', 'putih'),
  (now() - interval '2 hours', 'Pak Udin, guru olahraga', 'Lari keliling lapangan lima kali itu ternyata ada gunanya, Pak. Saya baru selesai lari 10K pertama.', null, 'kuning'),
  (now() - interval '1 hour', 'Ustazah Fatimah', 'Terima kasih sudah sabar ngajarin saya ngaji dari iqra satu. Doa Ibu selalu saya ingat.', 'Aisyah', 'merah_muda'),
  (now() - interval '20 minutes', 'Bu Siska, guru Bahasa Inggris', 'Ibu satu-satunya guru yang ngasih kami nonton film di kelas, terus nyuruh nulis ulasannya. Sekarang saya kerja pakai bahasa Inggris tiap hari.', 'Dimas', 'biru_muda');
